  $("yqFg").onclick = function(){ if(!E()){ msg("Type your email first.", 1); return; } AUTH.sendPasswordResetEmail(E()).then(function(){ msg("Password reset link sent to " + E() + "."); }).catch(function(e){ msg(errTxt(e), 1); }); };
